// Источник: проверка #cdbc90a6 07.10.2026 16:32–16:34 (session.json test_data «ערבית אשכנז קטע 3»), бриф .qa/research/cdbc90a6.md,
// кейс .qa/tests/admin/AD-06 (черновик не виден пользователю), скриншоты cdbc90a6-2-draft-unchanged-asis, cdbc90a6-4-changed-new-text,
// cdbc90a6-4-restore-entry, cdbc90a6-5-history-final. Тикет #cdbc90a6 (הושלם 07.10) + #a5decf4a.
// Опора: тикет #cdbc90a6 «מה רצוי» — «נוסח חדש אושר» только при реальном изменении текста, иначе «הטקסט אושר כפי שהיה»; F-102 AC5 (кто и когда);
// F-102 AC1 «טקסט שלא אושר אינו מוצג למשתמש» (черновик не виден). Решения пользователя 05.10/07.10: ערבית אשכנז קטע 3 можно утверждать,
// текст вернуть посимвольно (.qa/research/cdbc90a6/orig-arvit-ashkenaz-3.txt). Статус «מאושר» не откатывается — это норма.
// @data: в finally текст возвращается посимвольно и утверждается, черновик удаляется, аккаунт — USER1.
import { expect } from '@wdio/globals';
import { byTextContains, byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import {
  asAdmin, asUser1, backToUser1, openAdminPrayer, openSection, reopenSection, readBody, setBody, saveDraft, approveDraft,
  historyEntry, restoreSectionText, origArvit3, qaMarker, openUserArvit3,
} from '../_lib/admin.ts';

const PRAYER = 'ערבית', NUSACH = 'אשכנז', SECTION = 'המעריב ערבים';
const CHANGE = ' א';                                     // как 07.10 16:33: «שינוי זמני (נוסף ' א')»

describe('Админка в приложении: утверждение текста и история', () => {
  afterEach(async () => { await toHome(); });

  it('AD-05 קטע 3 «המעריב ערבים»: черновик без изменений → «הטקסט אושר כפי שהיה»; с « א» → черновик не виден USER1 → «נוסח חדש אושר»; оригинал возвращён #cdbc90a6 #a5decf4a @data', async () => {
    const orig = origArvit3();
    expect(orig.length).toBe(537);
    try {
      await asAdmin();

      // 1. Черновик БЕЗ изменений → «אישור ופרסום» → в истории «המעריב ערבים: הטקסט אושר כפי שהיה על ידי …» (своя метка).
      await openAdminPrayer(PRAYER, NUSACH);
      await openSection(SECTION);
      expect(await readBody()).toBe(orig);                // стартуем с оригинала
      await saveDraft();
      const m1 = qaMarker('ad05-asis');
      await approveDraft(m1);
      const e1 = await historyEntry(m1);
      await expect(e1).toHaveText(new RegExp(`${SECTION}: הטקסט אושר כפי שהיה על ידי .+\\d{1,2}\\.\\d{1,2}\\.\\d{4}`));
      await expect(e1).not.toHaveText(/נוסח חדש אושר/);

      // 2. Изменение « א» → «שמירת טיוטה» (без утверждения).
      await reopenSection(PRAYER, NUSACH, SECTION);
      await setBody(orig + CHANGE);
      await saveDraft();

      // 3. USER1: в «3 מתוך 15» прежний текст — без « א», строка «מקור: … · אושר על ידי …» на месте (F-102 AC1).
      await asUser1();
      await openUserArvit3();
      await scrollToText('הַמַּעֲרִיב עֲרָבִים');
      await expect(byTextContains(`הַמַּעֲרִיב עֲרָבִים:${CHANGE}`)).not.toBeDisplayed();
      await scrollToText('אושר על ידי');
      await expect(byTextMatches('(?s)מקור: .*אושר על ידי .*')).toBeDisplayed();

      // 4. ADMIN: утвердить черновик с « א» → в истории «המעריב ערבים: נוסח חדש אושר על ידי …» (своя метка).
      await asAdmin();
      await reopenSection(PRAYER, NUSACH, SECTION);
      expect(await readBody()).toBe(orig + CHANGE);       // черновик сохранился
      const m2 = qaMarker('ad05-new');
      await approveDraft(m2);
      const e2 = await historyEntry(m2);
      await expect(e2).toHaveText(new RegExp(`${SECTION}: נוסח חדש אושר על ידי .+\\d{1,2}\\.\\d{1,2}\\.\\d{4}`));

      // 5. Вернуть оригинал посимвольно и утвердить (в истории — «נוסח חדש אושר», текст снова изменился) — в finally.
    } finally {
      try {
        await asAdmin().catch(() => {});
        await restoreSectionText(PRAYER, NUSACH, SECTION, orig, 'ad05');
        await openAdminPrayer(PRAYER, NUSACH);
        await expect(byTextMatches('[1-9]\\d* מתוך 15 קטעים מאושרים')).toBeDisplayed();
      } finally {
        await backToUser1();
      }
    }
  });
});
